head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > E > onmousemove]<br/>Textarea 컴포넌트에서 마우스 포인터가 이동할 때 발생합니다.",
    "validation" : [
        "Textarea 컴포넌트에서 마우스 포인터가 이동할 때 onmousemove 이벤트가 발생합니다.",
        "이벤트 객체 e (MouseEvent) 가 핸들러에 전달됩니다.",
        "마우스 이동에 따라 onmousemove 이벤트가 연속적으로 발생합니다.",
    ]
}



// 마우스가 이동하는 동안 같은 이벤트 연속 발생 시 출력 폭주 방지용 카운트 (onmouseout 에서 리셋)
let eCount_mousemove = 0;



scwin.onpageload = function () {
    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let cList = $c.gcm.createCList({});
    let eList = $c.gcm.createEList(["onmousemove", "onmouseout"]);

    // target1 (textarea) 생성
    $c.gcm.createBasicTextArea(cList, eList);
}



// onmousemove 핸들러 - 마우스 이동 시 연속 발생, 출력은 3번까지만
scwin.target1_onmousemove = function (e) {
    if (eCount_mousemove < 3) {
        wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onmousemove 이벤트 발생=====");
        wf_body_bottom.getObj("scwin").setReturnValue("e : " + e);
        if (eCount_mousemove == 2) {
            wf_body_bottom.getObj("scwin").setReturnValue("...");
        }
    }
    eCount_mousemove += 1;
}


// onmouseout 핸들러 - 마우스가 textarea 영역 밖으로 나가면 카운트 리셋
scwin.target1_onmouseout = function (e) {
    eCount_mousemove = 0;
}
